using System.Data;using System.Data.Common;using System.Globalization;using System.Text.Json;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Storage;using Qms.Application.Security;using Qms.Application.Trainings;using Qms.Contracts.Common;using Qms.Contracts.Trainings;using Qms.Domain.AuditTrail;using Qms.Domain.QualityRecords;using Qms.Domain.Trainings;using Qms.Domain.Workflows;using Qms.Infrastructure.Persistence;
namespace Qms.Infrastructure.Trainings;
public sealed class TrainingService(QmsDbContext db,TimeProvider clock,ICurrentUser user):ITrainingService
{
 private static readonly Guid PrototypeDepartmentId=Guid.Parse("01991f70-6f40-7000-8000-000000000002");
 public async Task<PagedResponse<TrainingListItemResponse>>SearchAsync(TrainingSearchRequest r,CancellationToken ct){if(r.Page<1||r.PageSize is not(10 or 25 or 50 or 100))throw new ArgumentException("Sayfa ve sayfa boyutu geçersizdir.");var q=from assignment in db.TrainingAssignments.AsNoTracking() join qr in db.QualityRecords.AsNoTracking() on assignment.QualityRecordId equals qr.Id join d in db.ControlledDocuments.AsNoTracking() on assignment.ControlledDocumentId equals d.Id into ds from d in ds.DefaultIfEmpty() join rev in db.DocumentRevisions.AsNoTracking() on assignment.DocumentRevisionId equals rev.Id into revs from rev in revs.DefaultIfEmpty() select new Row{Assignment=assignment,RecordNumber=qr.RecordNumber,DocumentCode=d==null?null:d.DocumentCode,DocumentMajor=rev==null?(int?)null:rev.MajorVersion,DocumentMinor=rev==null?(int?)null:rev.MinorVersion};foreach(var f in r.Filters??[])q=Filter(q,f);var total=await q.LongCountAsync(ct);q=Sort(q,r.SortBy,r.SortDirection);var items=await q.Skip((r.Page-1)*r.PageSize).Take(r.PageSize).Select(x=>new TrainingListItemResponse(x.Assignment.Id,x.RecordNumber,x.Assignment.EmployeeUserId,x.Assignment.EmployeeName,x.Assignment.Position,x.Assignment.CourseCode,x.Assignment.CourseTitle,x.DocumentCode,x.DocumentMajor==null?null:x.DocumentMajor+"."+x.DocumentMinor,x.Assignment.AssessmentMode.ToString(),x.Assignment.DeliveryMethod.ToString(),x.Assignment.Status.ToString(),x.Assignment.ProgressPercent,x.Assignment.DueAtUtc,x.Assignment.ExpiresAtUtc,x.Assignment.IsCriticalQualification,x.Assignment.Attempts.Count,x.Assignment.CreatedAtUtc,x.Assignment.Version)).ToListAsync(ct);return new(items,r.Page,r.PageSize,total,total==0?0:(int)Math.Ceiling(total/(double)r.PageSize));}
 public async Task<TrainingDetailsResponse?>GetDetailsAsync(Guid id,CancellationToken ct){var x=await(from assignment in db.TrainingAssignments.AsNoTracking().Include(x=>x.Attempts) join qr in db.QualityRecords.AsNoTracking() on assignment.QualityRecordId equals qr.Id join d in db.ControlledDocuments.AsNoTracking() on assignment.ControlledDocumentId equals d.Id into ds from d in ds.DefaultIfEmpty() join rev in db.DocumentRevisions.AsNoTracking() on assignment.DocumentRevisionId equals rev.Id into revs from rev in revs.DefaultIfEmpty() where assignment.Id==id select new{Assignment=assignment,RecordNumber=qr.RecordNumber,DocumentCode=d==null?null:d.DocumentCode,DocumentMajor=rev==null?(int?)null:rev.MajorVersion,DocumentMinor=rev==null?(int?)null:rev.MinorVersion}).SingleOrDefaultAsync(ct);if(x is null)return null;var a=x.Assignment;var audit=await db.AuditEvents.AsNoTracking().Where(e=>e.AggregateType=="Training"&&e.AggregateId==id).OrderByDescending(e=>e.OccurredAtUtc).ToListAsync(ct);var record=new TrainingRecordResponse(a.Id,a.QualityRecordId,x.RecordNumber,a.MatrixRuleId,a.ControlledDocumentId,a.DocumentRevisionId,a.DocumentTrainingRequirementId,a.EmployeeUserId,a.EmployeeName,a.Position,a.CourseCode,a.CourseTitle,x.DocumentCode,x.DocumentMajor==null?null:$"{x.DocumentMajor}.{x.DocumentMinor}",a.AssessmentMode.ToString(),a.DeliveryMethod.ToString(),a.PassingScore,a.ValidityMonths,a.MaxAttempts,a.IsCriticalQualification,a.PlannedYear,a.SessionCode,a.Trainer,a.DueAtUtc,a.Status.ToString(),a.ProgressPercent,a.StartedAtUtc,a.AcknowledgedAtUtc,a.AcknowledgementMeaning,a.CompletedAtUtc,a.ExpiresAtUtc,a.TrainerApprovalNote,a.CreatedAtUtc,a.UpdatedAtUtc,a.Version);return new(record,a.Attempts.OrderByDescending(t=>t.AttemptNumber).Select(t=>new TrainingAttemptResponse(t.Id,t.AttemptNumber,t.Score,t.PracticalPassed,t.Passed,t.Evidence,t.Evaluator,t.AssessedAtUtc)).ToList(),audit.Select(e=>new TrainingAuditResponse(e.Id,e.AggregateVersion,e.EventType,e.ActorDisplayNameSnapshot,e.OccurredAtUtc,e.Reason,e.Payload.RootElement.Clone())).ToList(),Transitions(a.Status));}
 public async Task<TrainingDetailsResponse>CreateAsync(CreateTrainingAssignmentRequest r,CancellationToken ct){EnsureManager();var employee=await db.Users.Where(x=>x.Id==r.EmployeeUserId&&x.IsActive).Select(x=>new{x.DisplayName,x.DepartmentId}).SingleOrDefaultAsync(ct)??throw new ArgumentException("Etkin çalışan bulunamadı.");if(r.ControlledDocumentId is Guid did&&!await db.ControlledDocuments.AnyAsync(x=>x.Id==did,ct))throw new ArgumentException("Bağlı doküman bulunamadı.");if(!Enum.TryParse<TrainingAssessmentMode>(r.AssessmentMode,true,out var mode))throw new ArgumentException("Değerlendirme yöntemi geçersiz.");if(!Enum.TryParse<TrainingDeliveryMethod>(r.DeliveryMethod,true,out var delivery))throw new ArgumentException("Eğitim yöntemi geçersiz.");var now=clock.GetUtcNow();await using var tx=await db.Database.BeginTransactionAsync(ct);var seq=await NextNumber(now.Year,tx,ct);var number=$"EGT-{now.Year}-{seq:000000}";var qr=QualityRecord.Create(number,"training",user.Id,user.DepartmentId??PrototypeDepartmentId,now);if(r.AssignNow)qr.Submit(now);var a=TrainingAssignment.Create(qr.Id,r.MatrixRuleId,r.ControlledDocumentId,r.DocumentRevisionId,null,r.EmployeeUserId,employee.DisplayName,r.Position,r.CourseCode,r.CourseTitle,mode,delivery,r.PassingScore,r.ValidityMonths,r.MaxAttempts,r.IsCriticalQualification,r.DueAtUtc.ToUniversalTime(),r.SessionCode,r.Trainer,r.AssignNow,now);db.QualityRecords.Add(qr);db.TrainingAssignments.Add(a);if(r.AssignNow)db.WorkflowTaskAssignments.Add(WorkflowTaskAssignment.Create("Training",a.Id,WorkflowTaskRoles.Learner,r.EmployeeUserId,employee.DepartmentId,now,r.DueAtUtc));db.AuditEvents.Add(Audit(a,"TrainingAssignmentCreated",now,new{number,r.EmployeeUserId,r.ControlledDocumentId}));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return(await GetDetailsAsync(a.Id,ct))!;}
 public async Task<TrainingDetailsResponse?>TransitionAsync(Guid id,TransitionTrainingRequest r,CancellationToken ct){var a=await Load(id,ct);if(a is null)return null;var qr=await db.QualityRecords.SingleAsync(x=>x.Id==a.QualityRecordId,ct);var code=r.Transition.Trim().ToLowerInvariant();if(code is"start"or"submit-assessment"){if(a.EmployeeUserId!=user.Id&&!IsManager())throw new QmsForbiddenException("Bu eğitim görevi size atanmamış.");}else if(code=="approve"){EnsureTrainer();if(a.EmployeeUserId==user.Id&&!user.IsInRole(QmsRoles.Administrator))throw new QmsForbiddenException("Çalışan kendi eğitim yeterliliğini onaylayamaz.");}else EnsureManager();var now=clock.GetUtcNow();var from=a.Status;await using var tx=await db.Database.BeginTransactionAsync(ct);a.Transition(r.ExpectedVersion,code,r.Note,now);if(code=="assign"){qr.Submit(now);var dep=await db.Users.Where(x=>x.Id==a.EmployeeUserId).Select(x=>x.DepartmentId).SingleAsync(ct);db.WorkflowTaskAssignments.Add(WorkflowTaskAssignment.Create("Training",a.Id,WorkflowTaskRoles.Learner,a.EmployeeUserId,dep,now,a.DueAtUtc));}if(code=="submit-assessment"){await CompleteTasks(a.Id,WorkflowTaskRoles.Learner,now,ct);await AssignTrainer(a,now,ct);}if(code=="reassign"){var dep=await db.Users.Where(x=>x.Id==a.EmployeeUserId).Select(x=>x.DepartmentId).SingleAsync(ct);db.WorkflowTaskAssignments.Add(WorkflowTaskAssignment.Create("Training",a.Id,WorkflowTaskRoles.Learner,a.EmployeeUserId,dep,now,a.DueAtUtc));}if(code=="approve")await CompleteTasks(a.Id,WorkflowTaskRoles.Trainer,now,ct);if(code=="cancel")await CompleteAllTasks(a.Id,now,ct);if(a.Status==TrainingAssignmentStatus.Completed){qr.Close(now,false);await SyncDocumentRequirement(a,now,ct);}db.AuditEvents.Add(Audit(a,"TrainingStatusChanged",now,new{from=from.ToString(),to=a.Status.ToString(),transition=code},r.Note));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return await GetDetailsAsync(id,ct);}
 public async Task<TrainingDetailsResponse?>AcknowledgeAsync(Guid id,AcknowledgeTrainingRequest r,CancellationToken ct){var a=await Load(id,ct);if(a is null)return null;if(a.EmployeeUserId!=user.Id&&!IsManager())throw new QmsForbiddenException("Bu okuma görevi size atanmamış.");var now=clock.GetUtcNow();a.Acknowledge(r.ExpectedVersion,r.SignatureMeaning,now);db.AuditEvents.Add(Audit(a,"TrainingReadAcknowledged",now,new{a.DocumentRevisionId},r.SignatureMeaning));await db.SaveChangesAsync(ct);return await GetDetailsAsync(id,ct);}
 public async Task<TrainingDetailsResponse?>RecordAssessmentAsync(Guid id,RecordTrainingAssessmentRequest r,CancellationToken ct){EnsureTrainer();var a=await Load(id,ct);if(a is null)return null;var now=clock.GetUtcNow();var attempt=a.RecordAttempt(r.ExpectedVersion,r.Score,r.PracticalPassed,r.Evidence,user.DisplayName,now);db.TrainingAssessmentAttempts.Add(attempt);db.AuditEvents.Add(Audit(a,attempt.Passed?"TrainingAssessmentPassed":"TrainingAssessmentFailed",now,new{attempt.AttemptNumber,r.Score,r.PracticalPassed},r.Evidence));await db.SaveChangesAsync(ct);return await GetDetailsAsync(id,ct);}
 public async Task<IReadOnlyList<TrainingMatrixRuleResponse>>GetMatrixAsync(CancellationToken ct)=>await(from m in db.TrainingMatrixRules.AsNoTracking() join d in db.ControlledDocuments.AsNoTracking() on m.ControlledDocumentId equals d.Id into ds from d in ds.DefaultIfEmpty() orderby m.Position,m.CourseCode select new TrainingMatrixRuleResponse(m.Id,m.Position,m.CourseCode,m.CourseTitle,m.ControlledDocumentId,d==null?null:d.DocumentCode,m.AssessmentMode.ToString(),m.DeliveryMethod.ToString(),m.PassingScore,m.ValidityMonths,m.IsCriticalQualification,m.IsActive,m.EffectiveAtUtc)).ToListAsync(ct);
 public async Task<TrainingMatrixRuleResponse>CreateMatrixRuleAsync(CreateTrainingMatrixRuleRequest r,CancellationToken ct){EnsureManager();if(!Enum.TryParse<TrainingAssessmentMode>(r.AssessmentMode,true,out var mode)||!Enum.TryParse<TrainingDeliveryMethod>(r.DeliveryMethod,true,out var delivery))throw new ArgumentException("Eğitim veya değerlendirme yöntemi geçersiz.");if(await db.TrainingMatrixRules.AnyAsync(x=>x.Position==r.Position.Trim()&&x.CourseCode==r.CourseCode.Trim(),ct))throw new ArgumentException("Bu pozisyon ve eğitim kodu matris içinde zaten tanımlı.");string? documentCode=null;if(r.ControlledDocumentId is Guid did){documentCode=await db.ControlledDocuments.Where(x=>x.Id==did).Select(x=>x.DocumentCode).SingleOrDefaultAsync(ct)??throw new ArgumentException("Bağlı doküman bulunamadı.");}var m=TrainingMatrixRule.Create(r.Position,r.CourseCode,r.CourseTitle,r.ControlledDocumentId,mode,delivery,r.PassingScore,r.ValidityMonths,r.IsCriticalQualification,r.EffectiveAtUtc.ToUniversalTime(),clock.GetUtcNow());db.TrainingMatrixRules.Add(m);await db.SaveChangesAsync(ct);return new(m.Id,m.Position,m.CourseCode,m.CourseTitle,m.ControlledDocumentId,documentCode,m.AssessmentMode.ToString(),m.DeliveryMethod.ToString(),m.PassingScore,m.ValidityMonths,m.IsCriticalQualification,m.IsActive,m.EffectiveAtUtc);}
 public async Task<TrainingOptionsResponse>GetOptionsAsync(CancellationToken ct){var employees=await(from u in db.Users.AsNoTracking() join up in db.UserPositions.AsNoTracking().Where(x=>x.EndsAtUtc==null&&x.IsPrimary) on u.Id equals up.UserId join p in db.Positions.AsNoTracking() on up.PositionId equals p.Id where u.IsActive orderby u.DisplayName select new TrainingEmployeeOptionResponse(u.Id,u.DisplayName,p.Name)).ToListAsync(ct);var documents=await(from d in db.ControlledDocuments.AsNoTracking() join r in db.DocumentRevisions.AsNoTracking() on d.CurrentRevisionId equals r.Id where d.Status!=Qms.Domain.Documents.ControlledDocumentStatus.Archived orderby d.DocumentCode select new TrainingDocumentOptionResponse(d.Id,r.Id,d.DocumentCode,d.Title,r.MajorVersion+"."+r.MinorVersion)).ToListAsync(ct);return new(employees,documents,employees.Select(x=>x.Position).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x).ToList());}
 private async Task SyncDocumentRequirement(TrainingAssignment a,DateTimeOffset now,CancellationToken ct){if(a.DocumentTrainingRequirementId is not Guid req||a.ControlledDocumentId is not Guid docId)return;if(await db.TrainingAssignments.AnyAsync(x=>x.DocumentTrainingRequirementId==req&&x.Id!=a.Id&&x.Status!=TrainingAssignmentStatus.Completed,ct))return;var d=await db.ControlledDocuments.Include(x=>x.Revisions).Include(x=>x.TrainingRequirements).SingleAsync(x=>x.Id==docId,ct);var completedCount=await db.TrainingAssignments.CountAsync(x=>x.DocumentTrainingRequirementId==req&&x.Id!=a.Id&&x.Status==TrainingAssignmentStatus.Completed,ct)+1;d.CompleteTraining(d.Version,req,$"{a.CourseCode} · {completedCount} çalışan · M.05 yeterlilik zinciri tamamlandı",now);db.AuditEvents.Add(AuditEvent.Create("Document",d.Id,d.Version,"DocumentTrainingCompleted",user.Id,user.DisplayName,now,Guid.CreateVersion7().ToString(),JsonSerializer.SerializeToDocument(new{trainingAssignmentId=a.Id,requirementId=req,completedEmployeeCount=completedCount,source="M.05"})));}
 private async Task CompleteTasks(Guid id,string role,DateTimeOffset now,CancellationToken ct){var tasks=await db.WorkflowTaskAssignments.Where(x=>x.AggregateType=="Training"&&x.AggregateId==id&&x.TaskRole==role&&x.Status==WorkflowTaskStatus.Active).ToListAsync(ct);foreach(var task in tasks)task.Complete(now);}
 private async Task CompleteAllTasks(Guid id,DateTimeOffset now,CancellationToken ct){var tasks=await db.WorkflowTaskAssignments.Where(x=>x.AggregateType=="Training"&&x.AggregateId==id&&x.Status==WorkflowTaskStatus.Active).ToListAsync(ct);foreach(var task in tasks)task.Complete(now);}
 private async Task AssignTrainer(TrainingAssignment a,DateTimeOffset now,CancellationToken ct){var trainer=await(from ur in db.UserRoles.AsNoTracking() join role in db.Roles.AsNoTracking() on ur.RoleId equals role.Id join target in db.Users.AsNoTracking() on ur.UserId equals target.Id where(role.Name==QmsRoles.TrainingCoordinator||role.Name==QmsRoles.DepartmentManager||role.Name==QmsRoles.QualityAssurance)&&target.IsActive&&target.Id!=a.EmployeeUserId orderby role.Name==QmsRoles.TrainingCoordinator?0:1,target.DisplayName select new{target.Id,target.DepartmentId}).FirstOrDefaultAsync(ct);if(trainer is not null)db.WorkflowTaskAssignments.Add(WorkflowTaskAssignment.Create("Training",a.Id,WorkflowTaskRoles.Trainer,trainer.Id,trainer.DepartmentId,now,a.DueAtUtc));}
 private Task<TrainingAssignment?>Load(Guid id,CancellationToken ct)=>db.TrainingAssignments.Include(x=>x.Attempts).SingleOrDefaultAsync(x=>x.Id==id,ct);private bool IsManager()=>user.IsInRole(QmsRoles.Administrator)||user.IsInRole(QmsRoles.TrainingCoordinator)||user.IsInRole(QmsRoles.QualityAssurance);private void EnsureManager(){if(!IsManager())throw new QmsForbiddenException("Eğitim planlama için Eğitim Koordinatörü veya KG rolü gerekir.");}private void EnsureTrainer(){if(!IsManager()&&!user.IsInRole(QmsRoles.DepartmentManager))throw new QmsForbiddenException("Değerlendirme için Eğitmen, bölüm yöneticisi veya Eğitim Koordinatörü rolü gerekir.");}
 private static IReadOnlyList<TrainingTransitionResponse>Transitions(TrainingAssignmentStatus s)=>s switch{TrainingAssignmentStatus.Planned=>[new("assign","Çalışana ata",false)],TrainingAssignmentStatus.Assigned=>[new("start","Eğitimi başlat",false),new("cancel","İptal et",true)],TrainingAssignmentStatus.InProgress=>[new("submit-assessment","Değerlendirmeye gönder",false),new("cancel","İptal et",true)],TrainingAssignmentStatus.TrainerApproval=>[new("approve","Yeterliliği onayla",true)],TrainingAssignmentStatus.Failed or TrainingAssignmentStatus.Expired=>[new("reassign","Yeniden ata",false)],TrainingAssignmentStatus.Completed=>[new("expire","Süresini doldu olarak işaretle",false)],_=>[]};
 private AuditEvent Audit(TrainingAssignment a,string type,DateTimeOffset now,object payload,string? reason=null)=>AuditEvent.Create("Training",a.Id,a.Version,type,user.Id,user.DisplayName,now,Guid.CreateVersion7().ToString(),JsonSerializer.SerializeToDocument(payload),reason);
 private static IQueryable<Row>Filter(IQueryable<Row>q,ColumnFilterRequest f){var field=f.Field.Trim().ToLowerInvariant();var op=f.Operator.Trim().ToLowerInvariant();var v=f.Value?.Trim()??"";return field switch{"recordnumber"=>Txt(q,op,v,0),"employeename"=>Txt(q,op,v,1),"position"=>Txt(q,op,v,2),"coursecode"=>Txt(q,op,v,3),"coursetitle"=>Txt(q,op,v,4),"documentcode"=>Txt(q,op,v,5),"status"=>Enum.TryParse<TrainingAssignmentStatus>(v,true,out var s)?q.Where(x=>x.Assignment.Status==s):throw new ArgumentException("Eğitim durumu geçersiz."),"assessmentmode"=>Enum.TryParse<TrainingAssessmentMode>(v,true,out var m)?q.Where(x=>x.Assignment.AssessmentMode==m):throw new ArgumentException("Değerlendirme türü geçersiz."),"iscriticalqualification"=>bool.TryParse(v,out var b)?q.Where(x=>x.Assignment.IsCriticalQualification==b):q,"dueatutc"=>Date(q,op,f.Value,f.ValueTo,true),"expiresatutc"=>Date(q,op,f.Value,f.ValueTo,false),_=>throw new ArgumentException($"Filtrelenmesine izin verilmeyen kolon: {f.Field}")};}
 private static IQueryable<Row>Txt(IQueryable<Row>q,string op,string v,int f)=>f switch{0=>op=="equals"?q.Where(x=>x.RecordNumber==v):q.Where(x=>x.RecordNumber.ToLower().Contains(v.ToLower())),1=>op=="equals"?q.Where(x=>x.Assignment.EmployeeName==v):q.Where(x=>x.Assignment.EmployeeName.ToLower().Contains(v.ToLower())),2=>op=="equals"?q.Where(x=>x.Assignment.Position==v):q.Where(x=>x.Assignment.Position.ToLower().Contains(v.ToLower())),3=>op=="equals"?q.Where(x=>x.Assignment.CourseCode==v):q.Where(x=>x.Assignment.CourseCode.ToLower().Contains(v.ToLower())),4=>op=="equals"?q.Where(x=>x.Assignment.CourseTitle==v):q.Where(x=>x.Assignment.CourseTitle.ToLower().Contains(v.ToLower())),_=>op=="equals"?q.Where(x=>x.DocumentCode==v):q.Where(x=>x.DocumentCode!=null&&x.DocumentCode.ToLower().Contains(v.ToLower()))};
 private static IQueryable<Row>Date(IQueryable<Row>q,string op,string?a,string?b,bool due){var from=DateTimeOffset.Parse(a??"",CultureInfo.InvariantCulture).ToUniversalTime();var to=string.IsNullOrWhiteSpace(b)?from.AddDays(1):DateTimeOffset.Parse(b,CultureInfo.InvariantCulture).ToUniversalTime();return(op,due)switch{("before",true)=>q.Where(x=>x.Assignment.DueAtUtc<from),("after",true)=>q.Where(x=>x.Assignment.DueAtUtc>from),(_,true)=>q.Where(x=>x.Assignment.DueAtUtc>=from&&x.Assignment.DueAtUtc<to),("before",false)=>q.Where(x=>x.Assignment.ExpiresAtUtc<from),("after",false)=>q.Where(x=>x.Assignment.ExpiresAtUtc>from),_=>q.Where(x=>x.Assignment.ExpiresAtUtc>=from&&x.Assignment.ExpiresAtUtc<to)};}
 private static IQueryable<Row>Sort(IQueryable<Row>q,string field,string dir){var d=dir.Equals("desc",StringComparison.OrdinalIgnoreCase);return field.Trim().ToLowerInvariant()switch{"recordnumber"=>d?q.OrderByDescending(x=>x.RecordNumber):q.OrderBy(x=>x.RecordNumber),"employeename"=>d?q.OrderByDescending(x=>x.Assignment.EmployeeName):q.OrderBy(x=>x.Assignment.EmployeeName),"coursecode"=>d?q.OrderByDescending(x=>x.Assignment.CourseCode):q.OrderBy(x=>x.Assignment.CourseCode),"status"=>d?q.OrderByDescending(x=>x.Assignment.Status):q.OrderBy(x=>x.Assignment.Status),"dueatutc"=>d?q.OrderByDescending(x=>x.Assignment.DueAtUtc):q.OrderBy(x=>x.Assignment.DueAtUtc),_=>d?q.OrderByDescending(x=>x.Assignment.CreatedAtUtc):q.OrderBy(x=>x.Assignment.CreatedAtUtc)};}
 private async Task<long>NextNumber(int year,IDbContextTransaction tx,CancellationToken ct){var c=db.Database.GetDbConnection();if(c.State!=ConnectionState.Open)await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.Transaction=tx.GetDbTransaction();cmd.CommandText="INSERT INTO core.record_number_sequence (\"RecordType\", \"CalendarYear\", \"LastValue\") VALUES (@recordType, @calendarYear, 1) ON CONFLICT (\"RecordType\", \"CalendarYear\") DO UPDATE SET \"LastValue\" = core.record_number_sequence.\"LastValue\" + 1 RETURNING \"LastValue\";";Add(cmd,"recordType","training");Add(cmd,"calendarYear",year);return Convert.ToInt64(await cmd.ExecuteScalarAsync(ct),CultureInfo.InvariantCulture);}private static void Add(DbCommand c,string n,object v){var p=c.CreateParameter();p.ParameterName=n;p.Value=v;c.Parameters.Add(p);}private sealed class Row{public required TrainingAssignment Assignment{get;init;}public required string RecordNumber{get;init;}public string?DocumentCode{get;init;}public int?DocumentMajor{get;init;}public int?DocumentMinor{get;init;}}
}
